-- ── platform.error_code_registry（錯誤碼清冊，CONSTANTS §10 / API §5.2）─────────────
-- zh-TW 契約訊息，供客戶端可預期處理。413/503 屬容器/生命週期層（非 DB 清冊），不入此種子（API §5.2）。
INSERT INTO platform.error_code_registry (error_code, http_status, message_zh_tw, is_active) VALUES
  ('VALIDATION_ERROR',     400, '請求格式/參數錯誤',     TRUE),
  ('UNAUTHORIZED',         401, '請先登入',             TRUE),
  ('INSUFFICIENT_BALANCE', 402, '餘額不足',             TRUE),
  ('NOT_FOUND',            404, '找不到',               TRUE),
  ('CONFLICT',             409, '衝突（已存在/已擁有）', TRUE),
  ('RATE_LIMITED',         429, '請求過於頻繁',         TRUE),
  ('INTERNAL_ERROR',       500, '伺服器錯誤',           TRUE)
ON CONFLICT (error_code) DO UPDATE SET
  http_status   = EXCLUDED.http_status,
  message_zh_tw = EXCLUDED.message_zh_tw,
  is_active     = EXCLUDED.is_active;
